CREATE TABLE public.paralelo_acessos (user_id uuid PRIMARY KEY);
GRANT SELECT ON public.paralelo_acessos TO authenticated;
GRANT ALL ON public.paralelo_acessos TO service_role;
ALTER TABLE public.paralelo_acessos ENABLE ROW LEVEL SECURITY;
CREATE POLICY acesso_proprio ON public.paralelo_acessos FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
INSERT INTO public.paralelo_acessos(user_id) SELECT id FROM public.profiles WHERE id='55754d78-fc6c-4a8c-847c-04998dc661d8' AND ativo;
CREATE FUNCTION public.pode_comercial_paralelo() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.paralelo_acessos a JOIN public.profiles p ON p.id=a.user_id WHERE a.user_id=auth.uid() AND p.ativo); $$;
REVOKE ALL ON FUNCTION public.pode_comercial_paralelo() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pode_comercial_paralelo() TO authenticated;
CREATE TABLE public.paralelo_clientes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cnpj text NOT NULL UNIQUE, nome text NOT NULL, fiscal jsonb NOT NULL DEFAULT '{}', observacao text NOT NULL DEFAULT '', ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(cnpj ~ '^[0-9]{14}$'), CHECK(length(trim(nome))>0));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.paralelo_clientes TO authenticated;
GRANT ALL ON public.paralelo_clientes TO service_role;
ALTER TABLE public.paralelo_clientes ENABLE ROW LEVEL SECURITY;
CREATE POLICY exclusivo ON public.paralelo_clientes FOR ALL TO authenticated USING ((SELECT public.pode_comercial_paralelo())) WITH CHECK ((SELECT public.pode_comercial_paralelo()));
CREATE TABLE public.paralelo_regioes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cliente_id uuid NOT NULL REFERENCES public.paralelo_clientes(id), nome text NOT NULL, cidades jsonb NOT NULL DEFAULT '[]', lead_time integer, calendario text NOT NULL DEFAULT 'uteis_rj', observacao text NOT NULL DEFAULT '', ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cliente_id,nome), CHECK(length(trim(nome))>0), CHECK(lead_time IS NULL OR lead_time>=0), CHECK(jsonb_typeof(cidades)='array'), CHECK(calendario IN ('uteis_rj','corridos')));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.paralelo_regioes TO authenticated;
GRANT ALL ON public.paralelo_regioes TO service_role;
ALTER TABLE public.paralelo_regioes ENABLE ROW LEVEL SECURITY;
CREATE POLICY exclusivo ON public.paralelo_regioes FOR ALL TO authenticated USING ((SELECT public.pode_comercial_paralelo())) WITH CHECK ((SELECT public.pode_comercial_paralelo()));
CREATE INDEX paralelo_regioes_cliente ON public.paralelo_regioes(cliente_id,id);
CREATE TABLE public.paralelo_tarifas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), regiao_id uuid NOT NULL REFERENCES public.paralelo_regioes(id), vigente_de date NOT NULL, vigente_ate date, fator_cubagem numeric, componentes jsonb NOT NULL DEFAULT '[]', fiscal jsonb NOT NULL DEFAULT '{}', faixas jsonb NOT NULL DEFAULT '[]', observacao text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(vigente_ate IS NULL OR vigente_ate>=vigente_de), CHECK(fator_cubagem IS NULL OR fator_cubagem>0), CHECK(jsonb_typeof(componentes)='array'), CHECK(jsonb_typeof(faixas)='array'));
GRANT SELECT,INSERT ON public.paralelo_tarifas TO authenticated;
GRANT ALL ON public.paralelo_tarifas TO service_role;
ALTER TABLE public.paralelo_tarifas ENABLE ROW LEVEL SECURITY;
CREATE POLICY exclusivo_ler ON public.paralelo_tarifas FOR SELECT TO authenticated USING ((SELECT public.pode_comercial_paralelo()));
CREATE POLICY exclusivo_inserir ON public.paralelo_tarifas FOR INSERT TO authenticated WITH CHECK ((SELECT public.pode_comercial_paralelo()));
CREATE INDEX paralelo_tarifas_regiao ON public.paralelo_tarifas(regiao_id,vigente_de,id);
CREATE TABLE public.paralelo_historico (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, tabela text NOT NULL, registro_id uuid NOT NULL, autor uuid, acao text NOT NULL, antes jsonb, depois jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.paralelo_historico TO authenticated;
GRANT ALL ON public.paralelo_historico TO service_role;
ALTER TABLE public.paralelo_historico ENABLE ROW LEVEL SECURITY;
CREATE POLICY exclusivo_ler ON public.paralelo_historico FOR SELECT TO authenticated USING ((SELECT public.pode_comercial_paralelo()));
CREATE FUNCTION public.paralelo_auditar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN NEW.updated_at=now(); END IF; INSERT INTO public.paralelo_historico(tabela,registro_id,autor,acao,antes,depois) VALUES(TG_TABLE_NAME,COALESCE(NEW.id,OLD.id),auth.uid(),TG_OP,CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END); RETURN COALESCE(NEW,OLD); END; $$;
REVOKE ALL ON FUNCTION public.paralelo_auditar() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER paralelo_clientes_audit BEFORE INSERT OR UPDATE OR DELETE ON public.paralelo_clientes FOR EACH ROW EXECUTE FUNCTION public.paralelo_auditar();
CREATE TRIGGER paralelo_regioes_audit BEFORE INSERT OR UPDATE OR DELETE ON public.paralelo_regioes FOR EACH ROW EXECUTE FUNCTION public.paralelo_auditar();
CREATE TRIGGER paralelo_tarifas_audit BEFORE INSERT ON public.paralelo_tarifas FOR EACH ROW EXECUTE FUNCTION public.paralelo_auditar();
CREATE FUNCTION public.paralelo_fontes(p_inicio date,p_fim date,p_cursor text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE resultado jsonb; BEGIN IF NOT public.pode_comercial_paralelo() THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF; IF p_inicio IS NULL OR p_fim IS NULL OR p_fim<p_inicio OR p_fim-p_inicio>62 THEN RAISE EXCEPTION 'Selecione até 63 dias'; END IF; SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.chave_cte),'[]') INTO resultado FROM (SELECT d.chave_cte,d.numero_cte,d.data_emissao,d.municipio_fim,d.uf_fim,d.cfop,d.icms,d.componentes,d.quantidades,d.valor_carga,d.valor_total_prestacao, (SELECT jsonb_agg(to_jsonb(n)) FROM (SELECT DISTINCT nf.cnpj_emitente,nf.razao_social_emitente,nf.dest_cidade,nf.dest_uf FROM public.ctes c JOIN public.notas_fiscais nf ON nf.id=c.nf_id WHERE c.chave_cte=d.chave_cte) n) notas FROM public.cte_detalhes d WHERE d.chave_cte>p_cursor AND d.data_emissao BETWEEN p_inicio AND p_fim ORDER BY d.chave_cte LIMIT 201) t; RETURN resultado; END; $$;
REVOKE ALL ON FUNCTION public.paralelo_fontes(date,date,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.paralelo_fontes(date,date,text) TO authenticated;
CREATE FUNCTION public.paralelo_clientes_fontes(p_cursor uuid DEFAULT '00000000-0000-0000-0000-000000000000') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE resultado jsonb; BEGIN IF NOT public.pode_comercial_paralelo() THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF; SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.id),'[]') INTO resultado FROM (SELECT id,cnpj,razao_social,nome_fantasia FROM public.embarcadores WHERE id>p_cursor AND ativo ORDER BY id LIMIT 201) t; RETURN resultado; END; $$;
REVOKE ALL ON FUNCTION public.paralelo_clientes_fontes(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.paralelo_clientes_fontes(uuid) TO authenticated;